"""Hidden behavioral tests for jo: cli. Generated by pbkit from the gold binary."""


def test_version(run):
    '-v prints the version and exits'
    r = run(args=['-v'])
    assert r.stdout == b'jo 1.9\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_version_json(run):
    r = run(args=['-V'])
    assert r.stdout == b'{"program":"jo","author":"Jan-Piet Mens","repo":"https://github.com/jpmens/jo","version":"1.9"}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_version_json_pretty(run):
    r = run(args=['-p', '-V'])
    assert r.stdout == b'{\n   "program": "jo",\n   "author": "Jan-Piet Mens",\n   "repo": "https://github.com/jpmens/jo",\n   "version": "1.9"\n}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_version_json_pretty_after(run):
    r = run(args=['-V', '-p'])
    assert r.stdout == b'{\n   "program": "jo",\n   "author": "Jan-Piet Mens",\n   "repo": "https://github.com/jpmens/jo",\n   "version": "1.9"\n}\n'
    assert r.stderr == b''
    assert r.returncode == 0


