def test_options_after_words_are_options(run):
    'glibc getopt permutes argv'
    r = run(args=['a=1', '-p', 'b=2'])
    assert r.stdout == b'{\n   "a": 1,\n   "b": 2\n}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_array_flag_after_word(run):
    r = run(args=['x', '-a', 'y'])
    assert r.stdout == b'["x","y"]\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_double_dash_stops_options(run):
    r = run(args=['--', '-p', 'a=1'])
    assert r.stdout == b'{"a":1}\n'
    assert r.stderr == b"Argument `-p' is neither k=v nor k@v\n"
    assert r.returncode == 0


def test_double_dash_then_dash_word(run):
    r = run(args=['-a', '--', '-x', '-'])
    assert r.stdout == b'["-x","-"]\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_single_dash_word(run):
    r = run(args=['-a', '-'])
    assert r.stdout == b'["-"]\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_clustered_flags(run):
    r = run(args=['-pa', '1', '2'])
    assert r.stdout == b'[\n   1,\n   2\n]\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_clustered_flags_with_arg(run):
    r = run(args=['-pd.', 'a.b=1'])
    assert r.stdout == b'{\n   "a": {\n      "b": 1\n   }\n}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_d_attached_argument(run):
    r = run(args=['-d/', 'a/b=1'])
    assert r.stdout == b'{"a":{"b":1}}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_d_multichar_uses_first(run):
    r = run(args=['-d', '::', 'a:b=1', 'a::c=2'])
    assert r.stdout == b'{"a":{"b":1,"":{"c":2}}}\n'
    assert r.stderr == b''
    assert r.returncode == 0


